def is_Monotonic(arr):
    if len(arr) < 2:
        return True

    # Determine the direction: increasing, decreasing, or unknown (if equal elements)
    increasing = decreasing = True

    for i in range(1, len(arr)):
        if arr[i] > arr[i - 1]:
            decreasing = False
        if arr[i] < arr[i - 1]:
            increasing = False

        # Early exit if both flags are false
        if not increasing and not decreasing:
            return False

    return True
